[CmdletBinding()]
param([Parameter(Mandatory)][string]$ConfigPath,[Parameter(Mandatory)][int]$DocumentId,[Parameter(Mandatory)][string]$ReportPath)
$ErrorActionPreference='Stop'
Import-Module (Join-Path $PSScriptRoot 'JournalInDesignScript.psm1') -Force
$config=Get-Content -LiteralPath $ConfigPath -Raw -Encoding UTF8|ConvertFrom-Json
if($config.articlePageRange){throw 'EXISTING_ARTICLE_COPY_REQUIRED'}
if([IO.Path]::GetFileName($config.documentPath) -notmatch '(QA|copy|副本)'){throw 'QA_REQUIRED'}
$figureAssets=@($config.assets|Where-Object {$_.kind -eq 'figure'})
foreach($asset in $figureAssets){
    if(-not(Test-Path -LiteralPath $asset.path -PathType Leaf)){throw "FIGURE_LINK_SOURCE_MISSING $($asset.name)"}
    if($asset.sha256 -and (Get-FileHash -LiteralPath $asset.path -Algorithm SHA256).Hash -ine $asset.sha256){throw "FIGURE_SOURCE_HASH_CHANGED $($asset.name)"}
}
$spec=@{id=$DocumentId;path=$config.documentPath;config=$config;figureAssets=@($figureAssets);progressPath=([IO.Path]::GetFullPath($ReportPath)+'.progress.json')}|ConvertTo-Json -Depth 90 -Compress
$code=[IO.File]::ReadAllText((Join-Path $PSScriptRoot 'journal_regression_snapshot.jsxinc'))+[IO.File]::ReadAllText((Join-Path $PSScriptRoot 'journal_merge_safety.jsxinc'))+[IO.File]::ReadAllText((Join-Path $PSScriptRoot 'journal_layout_rules.jsxinc'))+[IO.File]::ReadAllText((Join-Path $PSScriptRoot 'journal_article_assembly.jsxinc'))+"var ExistingReviewSpec=$spec;"+@'
(function(s){var ui=app.scriptPreferences.userInteractionLevel,redraw=app.scriptPreferences.enableRedraw;try{app.scriptPreferences.userInteractionLevel=UserInteractionLevels.NEVER_INTERACT;app.scriptPreferences.enableRedraw=false;var d=app.documents.itemByID(s.id);if(d.fullName.fsName!==File(s.path).fsName)throw Error('DOC_ID_PATH');var texts=[],characters=[],paragraphs=[],i;for(i=0;i<d.stories.length;i++)texts.push({id:d.stories[i].id,text:String(d.stories[i].contents)});var a=d.allCharacterStyles;for(i=0;i<a.length;i++)characters.push({id:a[i].id,signature:JournalMergeSafety.characterStyleSignature(a[i])});a=d.allParagraphStyles;for(i=0;i<a.length;i++)paragraphs.push({id:a[i].id,name:a[i].name,size:String(a[i].pointSize),leading:String(a[i].leading),font:String(a[i].appliedFont),face:String(a[i].fontStyle)});
var stages=[];function stage(name){stages.push({stage:name,timeMs:new Date().getTime()});var f=File(s.progressPath);f.encoding='UTF-8';if(!f.open('w'))throw Error('PROGRESS_WRITE');f.write(JournalRegressionSnapshot.json({documentId:d.id,path:s.path,stages:stages}));f.close();}stage('relink');var relinked=JournalMergeSafety.relinkFigures(d,s.figureAssets||[]);stage('source-format');var sourceFormatErrors=JournalLayout.sourceTextFormatting(d,s.config,true);if(sourceFormatErrors.length)throw Error('SOURCE_FORMAT_REPAIR '+sourceFormatErrors.join(';'));stage('table-format');JournalLayout.applySourceTableFormatting(d,s.config);for(i=0;i<d.stories.length;i++){for(var sp=0;sp<d.stories[i].paragraphs.length;sp++)JournalLayout.applySpecialGlyphs(d.stories[i].paragraphs[sp]);for(var st=0;st<d.stories[i].tables.length;st++)for(var ce=0;ce<d.stories[i].tables[st].cells.length;ce++)JournalLayout.applySpecialGlyphs(d.stories[i].tables[st].cells[ce].texts[0]);}var affiliations=0;for(i=0;i<d.stories.length;i++)for(var j=0;j<d.stories[i].paragraphs.length;j++){var p=d.stories[i].paragraphs[j];if(p.appliedParagraphStyle.name==='英文作者单位'){JournalLayout.applyEnglishAffiliationSpacing(p);affiliations++;}}
stage('typography');var biography=JournalLayout.repairBiographyHeadingLeading(d),formulaSpacing=JournalLayout.formulaLineSpacing(d,true);JournalLayout.repairOrphans(d);var finalRecovery=JournalLayout.prepareFinalPageReflow(d);stage('geometry');JournalLayout.geometry(d,s.config);stage('local-bottom');JournalLayout.alignLocalBlocks(d,s.config);var bodies=[];for(i=0;i<d.stories.length;i++)if(d.stories[i].extractLabel('journal-role')==='body')bodies.push(d.stories[i]);if(bodies.length!==1)throw Error('BODY_REQUIRED');var removedBlankPages=JournalArticleAssembly.trimTrailingBlankPages(d,bodies[0]);stage('last-page');var lastPageBalanced=JournalLayout.balanceLastPage(d);JournalLayout.formulaLineSpacing(d,true);d.recompose();
stage('preservation-check');for(i=0;i<texts.length;i++)if(String(d.stories.itemByID(texts[i].id).contents)!==texts[i].text)throw Error('EXISTING_TEXT_CHANGED');if(d.allCharacterStyles.length!==characters.length||d.allParagraphStyles.length!==paragraphs.length)throw Error('STYLE_COUNT_CHANGED');for(i=0;i<characters.length;i++)if(JournalMergeSafety.characterStyleSignature(d.characterStyles.itemByID(characters[i].id))!==characters[i].signature)throw Error('CHARACTER_DEFINITION_CHANGED '+characters[i].id);for(i=0;i<paragraphs.length;i++){var expected=paragraphs[i],current=d.paragraphStyles.itemByID(expected.id);if(current.name!==expected.name||String(current.pointSize)!==expected.size||String(current.leading)!==expected.leading||String(current.appliedFont)!==expected.font||String(current.fontStyle)!==expected.face)throw Error('PARAGRAPH_DEFINITION_CHANGED '+expected.id);}stage('save');d.save();return JournalRegressionSnapshot.json({status:'existing-copy-prepared-awaiting-full-check',documentId:d.id,path:d.fullName.fsName,affiliations:affiliations,relinkedFigures:relinked,biography:biography,formulaSpacing:formulaSpacing,finalRecovery:finalRecovery,lastPageBalanced:lastPageBalanced,removedBlankPages:removedBlankPages,styleDefinitionsPreserved:true,sourceTextPreserved:true});}catch(e){return 'ERROR '+e+' LINE '+e.line;}finally{app.scriptPreferences.userInteractionLevel=ui;app.scriptPreferences.enableRedraw=redraw;}})(ExistingReviewSpec);
'@
$app=New-Object -ComObject InDesign.Application.2020
$raw=[string](Invoke-JournalInDesignScript -Application $app -Code $code)
if(-not $raw -or $raw -eq 'null'){throw 'NATIVE_PREPARATION_RESULT_EMPTY'}
if($raw.StartsWith('ERROR')){throw $raw}
$result=$raw|ConvertFrom-Json
if(-not $result -or $result.status -ne 'existing-copy-prepared-awaiting-full-check' -or $result.documentId -ne $DocumentId -or -not $result.styleDefinitionsPreserved -or -not $result.sourceTextPreserved){throw 'NATIVE_PREPARATION_RESULT_INVALID'}
[IO.File]::WriteAllText([IO.Path]::GetFullPath($ReportPath),($result|ConvertTo-Json -Depth 30),[Text.UTF8Encoding]::new($false))
$result
